package com.smartinterview.entity;

import com.fasterxml.jackson.annotation.JsonIgnore;
import com.smartinterview.entity.enums.DifficultyLevel;
import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;

/**
 * InterviewQuestion entity representing an individual question generated by AI
 * during an interview session.
 */
@Entity
@Table(name = "interview_questions", indexes = {
    @Index(name = "idx_question_session_id", columnList = "interview_session_id")
})
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class InterviewQuestion {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @JsonIgnore
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "interview_session_id", nullable = false)
    private InterviewSession interviewSession;

    @Column(name = "question_order", nullable = false)
    private Integer questionOrder;

    @Lob
    @Column(name = "question_text", nullable = false, columnDefinition = "TEXT")
    private String questionText;

    @Column(length = 100)
    private String category;

    @Column(name = "target_skill", length = 100)
    private String targetSkill;

    @Enumerated(EnumType.STRING)
    @Column(name = "difficulty_level", nullable = false, length = 20)
    @Builder.Default
    private DifficultyLevel difficultyLevel = DifficultyLevel.MEDIUM;

    @Lob
    @Column(name = "expected_key_points_json", columnDefinition = "TEXT")
    private String expectedKeyPointsJson;

    @Lob
    @Column(name = "selection_reasons_json", columnDefinition = "LONGTEXT")
    @Builder.Default
    private String selectionReasonsJson = "[]";

    @OneToOne(mappedBy = "interviewQuestion", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.LAZY)
    private CandidateAnswer candidateAnswer;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    @PrePersist
    protected void onPrePersist() {
        if (this.createdAt == null) {
            this.createdAt = LocalDateTime.now();
        }
    }
}
